// SettingsKit from C# in about forty lines: open a settings file,
// set two values, save atomically, read one back.
//
// The binding in SettingsKit.cs (same folder) was generated by
// BridgeKit from the kit's shipped header - it is not hand-written:
//
//     bridgekit gen-cs --header settingskit.h --dll-name settings_kit.dll --out SettingsKit.cs
//
// Put settings_kit.dll (from the SettingsKit release zip) next to
// the compiled program, then `dotnet run`.
//
// The pattern to notice: reading with a default never writes the
// default into the file. Only values you set are stored, so changing
// a default in your next release cannot silently change the meaning
// of files already on your users' disks.

using System;
using BridgeKit.Generated;

internal static class Program
{
    private static void Check(int rc, string what)
    {
        if (rc != 0)
        {
            string err = SettingsKit.sk_last_error_string() ?? "unknown error";
            throw new InvalidOperationException($"{what} failed: {err} (code {rc})");
        }
    }

    private static void Main()
    {
        Console.WriteLine($"SettingsKit version: {SettingsKit.sk_version_string()}");

        // Schema 1, no flags, no migrations needed for a fresh file.
        Check(SettingsKit.sk_open("settings.json", 1, 0, out IntPtr doc), "open");
        try
        {
            Check(SettingsKit.sk_set_string(doc, "downloads.preset", "720p"), "set preset");
            Check(SettingsKit.sk_set_i64(doc, "ui.width", 1280), "set width");
            Check(SettingsKit.sk_save(doc), "save");   // atomic replace on disk

            string preset = SettingsKit.sk_get_string_string(doc, "downloads.preset", "1080p", out int found);
            Console.WriteLine($"preset = {preset} (found: {found == 1})");

            // A key that was never set reads as its default and is
            // NOT written to the file.
            long height = 0;
            Check(SettingsKit.sk_get_i64(doc, "ui.height", 720, out height, out int heightFound), "get height");
            Console.WriteLine($"height = {height} (found: {heightFound == 1})");
        }
        finally
        {
            SettingsKit.sk_close(doc);
        }
    }
}
